PRAGMA foreign_keys = ON;
CREATE TABLE job_roles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE officials (id TEXT PRIMARY KEY, employee_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, job_role_id TEXT NOT NULL REFERENCES job_roles(id), is_demo_selectable INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE administrators (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE competencies (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, domain TEXT NOT NULL, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE competency_matrices (id TEXT PRIMARY KEY, job_role_id TEXT NOT NULL REFERENCES job_roles(id), name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE matrix_versions (id TEXT PRIMARY KEY, matrix_id TEXT NOT NULL REFERENCES competency_matrices(id), version INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), published_at TEXT, created_by TEXT REFERENCES administrators(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(matrix_id, version));
CREATE TABLE matrix_competencies (id TEXT PRIMARY KEY, matrix_version_id TEXT NOT NULL REFERENCES matrix_versions(id), competency_id TEXT NOT NULL REFERENCES competencies(id), required_level REAL NOT NULL CHECK(required_level BETWEEN 1 AND 5), importance REAL NOT NULL CHECK(importance BETWEEN 1 AND 3), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(matrix_version_id, competency_id));
CREATE TABLE questions (id TEXT PRIMARY KEY, competency_id TEXT NOT NULL REFERENCES competencies(id), kind TEXT NOT NULL, prompt TEXT NOT NULL, options_json TEXT, answer_key_json TEXT, rubric_json TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assessments (id TEXT PRIMARY KEY, official_id TEXT NOT NULL REFERENCES officials(id), matrix_version_id TEXT NOT NULL REFERENCES matrix_versions(id), status TEXT NOT NULL DEFAULT 'active', started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assessment_rounds (id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id), round_number INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(assessment_id, round_number));
CREATE TABLE responses (id TEXT PRIMARY KEY, round_id TEXT NOT NULL REFERENCES assessment_rounds(id), question_id TEXT REFERENCES questions(id), prompt_snapshot TEXT NOT NULL, response_json TEXT NOT NULL, submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE evidence (id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id), competency_id TEXT NOT NULL REFERENCES competencies(id), source_type TEXT NOT NULL, level REAL NOT NULL, reliability REAL NOT NULL, rationale TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assessment_results (id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id), competency_id TEXT NOT NULL REFERENCES competencies(id), assessed_level REAL NOT NULL, required_level REAL NOT NULL, gap REAL NOT NULL, priority REAL NOT NULL, confidence REAL NOT NULL, supported INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(assessment_id, competency_id));
CREATE TABLE courses (id TEXT PRIMARY KEY, source TEXT NOT NULL, source_url TEXT NOT NULL, title TEXT NOT NULL, provider TEXT, duration TEXT, level TEXT, rating REAL, thumbnail_url TEXT, detail_available INTEGER NOT NULL, incomplete_source INTEGER NOT NULL DEFAULT 1, search_terms_json TEXT NOT NULL, domains_json TEXT NOT NULL, detail_json TEXT, provenance_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE course_competencies (course_id TEXT NOT NULL REFERENCES courses(id), competency_id TEXT NOT NULL REFERENCES competencies(id), evidence_type TEXT NOT NULL, relevance REAL NOT NULL DEFAULT 0, UNIQUE(course_id, competency_id));
CREATE TABLE recommendations (id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES assessments(id), competency_id TEXT NOT NULL REFERENCES competencies(id), course_id TEXT NOT NULL REFERENCES courses(id), rank INTEGER NOT NULL, rationale TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE course_completions (id TEXT PRIMARY KEY, official_id TEXT NOT NULL REFERENCES officials(id), course_id TEXT NOT NULL REFERENCES courses(id), completed_at TEXT NOT NULL, verified_assessment_level REAL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE learning_history (id TEXT PRIMARY KEY, official_id TEXT NOT NULL REFERENCES officials(id), competency_id TEXT NOT NULL REFERENCES competencies(id), source_type TEXT NOT NULL, source_id TEXT NOT NULL, level REAL NOT NULL, reliability REAL NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER published_matrix_version_immutable BEFORE UPDATE ON matrix_versions WHEN OLD.status = 'published' BEGIN SELECT RAISE(ABORT, 'published matrix versions are immutable'); END;
CREATE TRIGGER published_matrix_version_no_delete BEFORE DELETE ON matrix_versions WHEN OLD.status = 'published' BEGIN SELECT RAISE(ABORT, 'published matrix versions are immutable'); END;
CREATE TRIGGER published_matrix_competency_immutable_update BEFORE UPDATE ON matrix_competencies WHEN EXISTS (SELECT 1 FROM matrix_versions WHERE id = OLD.matrix_version_id AND status = 'published') BEGIN SELECT RAISE(ABORT, 'published matrix versions are immutable'); END;
CREATE TRIGGER published_matrix_competency_immutable_delete BEFORE DELETE ON matrix_competencies WHEN EXISTS (SELECT 1 FROM matrix_versions WHERE id = OLD.matrix_version_id AND status = 'published') BEGIN SELECT RAISE(ABORT, 'published matrix versions are immutable'); END;
CREATE TRIGGER published_matrix_competency_immutable_insert BEFORE INSERT ON matrix_competencies WHEN EXISTS (SELECT 1 FROM matrix_versions WHERE id = NEW.matrix_version_id AND status = 'published') BEGIN SELECT RAISE(ABORT, 'published matrix versions are immutable'); END;
